mod linalg {
    use std::fmt;
    use std::ops::{Add, Index, IndexMut, Mul, Sub};
    use std::str::FromStr;

    #[derive(Debug, Clone, PartialEq)]
    pub struct Matrix {
        rows: usize,
        cols: usize,
        data: Vec<f64>,
    }

    #[derive(Debug, PartialEq)]
    pub enum MatrixError {
        Empty,
        Ragged,
        Shape { left: (usize, usize), right: (usize, usize) },
        NotSquare,
        Parse(String),
    }

    impl Matrix {
        pub fn zeros(rows: usize, cols: usize) -> Matrix {
            Matrix { rows, cols, data: vec![0.0; rows * cols] }
        }

        pub fn identity(n: usize) -> Matrix {
            let mut m = Matrix::zeros(n, n);
            for i in 0..n {
                m[(i, i)] = 1.0;
            }
            m
        }

        pub fn from_rows(rows: Vec<Vec<f64>>) -> Result<Matrix, MatrixError> {
            let cols = rows.first().map(|r| r.len()).unwrap_or(0);
            if rows.is_empty() || cols == 0 {
                return Err(MatrixError::Empty);
            }
            for r in &rows {
                if r.len() != cols {
                    return Err(MatrixError::Ragged);
                }
            }
            let row_count = rows.len();
            let mut data = Vec::with_capacity(row_count * cols);
            for r in rows {
                data.extend(r);
            }
            Ok(Matrix { rows: row_count, cols, data })
        }

        pub fn shape(&self) -> (usize, usize) {
            (self.rows, self.cols)
        }

        pub fn transpose(&self) -> Matrix {
            let mut t = Matrix::zeros(self.cols, self.rows);
            for r in 0..self.rows {
                for c in 0..self.cols {
                    t[(c, r)] = self[(r, c)];
                }
            }
            t
        }

        pub fn try_mul(&self, other: &Matrix) -> Result<Matrix, MatrixError> {
            if self.cols != other.rows {
                return Err(MatrixError::Shape { left: self.shape(), right: other.shape() });
            }
            let mut out = Matrix::zeros(self.rows, other.cols);
            for r in 0..self.rows {
                for c in 0..other.cols {
                    out[(r, c)] = (0..self.cols).map(|k| self[(r, k)] * other[(k, c)]).sum();
                }
            }
            Ok(out)
        }

        pub fn determinant(&self) -> Result<f64, MatrixError> {
            if self.rows != self.cols {
                return Err(MatrixError::NotSquare);
            }
            let n = self.rows;
            let mut a = self.data.clone();
            let mut det = 1.0;
            for col in 0..n {
                let mut pivot = col;
                for i in col + 1..n {
                    if a[i * n + col].abs() >= a[pivot * n + col].abs() {
                        pivot = i;
                    }
                }
                if a[pivot * n + col].abs() < 1e-12 {
                    return Ok(0.0);
                }
                if pivot != col {
                    for k in 0..n {
                        a.swap(pivot * n + k, col * n + k);
                    }
                    det = -det;
                }
                let p = a[col * n + col];
                det *= p;
                for row in col + 1..n {
                    let factor = a[row * n + col] / p;
                    for k in col..n {
                        a[row * n + k] -= factor * a[col * n + k];
                    }
                }
            }
            Ok(det)
        }

        fn check_same_shape(&self, other: &Matrix, op: &str) {
            if self.shape() != other.shape() {
                panic!("{op}: shape mismatch {:?} vs {:?}", self.shape(), other.shape());
            }
        }
    }

    impl Index<(usize, usize)> for Matrix {
        type Output = f64;
        fn index(&self, (r, c): (usize, usize)) -> &f64 {
            assert!(r < self.rows && c < self.cols, "index ({r}, {c}) outside {}x{}", self.rows, self.cols);
            &self.data[r * self.cols + c]
        }
    }

    impl IndexMut<(usize, usize)> for Matrix {
        fn index_mut(&mut self, (r, c): (usize, usize)) -> &mut f64 {
            assert!(r < self.rows && c < self.cols, "index ({r}, {c}) outside {}x{}", self.rows, self.cols);
            &mut self.data[r * self.cols + c]
        }
    }

    impl Add<&Matrix> for &Matrix {
        type Output = Matrix;
        fn add(self, other: &Matrix) -> Matrix {
            self.check_same_shape(other, "add");
            let mut out = self.clone();
            for i in 0..out.data.len() {
                out.data[i] += other.data[i];
            }
            out
        }
    }

    impl Sub<&Matrix> for &Matrix {
        type Output = Matrix;
        fn sub(self, other: &Matrix) -> Matrix {
            self.check_same_shape(other, "sub");
            let mut out = self.clone();
            for i in 0..out.data.len() {
                out.data[i] -= other.data[i];
            }
            out
        }
    }

    impl Mul<f64> for &Matrix {
        type Output = Matrix;
        fn mul(self, k: f64) -> Matrix {
            Matrix { rows: self.rows, cols: self.cols, data: self.data.iter().map(|x| x * k).collect() }
        }
    }

    impl Mul<&Matrix> for &Matrix {
        type Output = Matrix;
        fn mul(self, other: &Matrix) -> Matrix {
            match self.try_mul(other) {
                Ok(m) => m,
                Err(e) => panic!("mul: shape mismatch {e:?}"),
            }
        }
    }

    impl fmt::Display for Matrix {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            let mut lines: Vec<String> = Vec::new();
            for row in self.data.chunks(self.cols) {
                let numbers: Vec<String> = row.iter().map(|x| format!("{x:.2}")).collect();
                lines.push(numbers.join(" "));
            }
            write!(f, "{}", lines.join("\n"))
        }
    }

    impl FromStr for Matrix {
        type Err = MatrixError;
        fn from_str(s: &str) -> Result<Matrix, MatrixError> {
            let mut rows = Vec::new();
            for row in s.split(';') {
                let mut values = Vec::new();
                for word in row.split_whitespace() {
                    values.push(word.parse::<f64>().map_err(|_| MatrixError::Parse(word.to_string()))?);
                }
                rows.push(values);
            }
            Matrix::from_rows(rows)
        }
    }
}

use linalg::{Matrix, MatrixError};

unitTests:
let m = |s: &str| s.parse::<Matrix>().unwrap();

test("building and shapes", || {
    check_eq(Matrix::from_rows(vec![vec![1.0, 2.0], vec![3.0, 4.0]]).map(|x| x.shape()), Ok((2, 2)));
    check_eq(Matrix::from_rows(vec![]), Err(MatrixError::Empty));
    check_eq(Matrix::from_rows(vec![vec![]]), Err(MatrixError::Empty));
    check_eq(Matrix::from_rows(vec![vec![1.0], vec![1.0, 2.0]]), Err(MatrixError::Ragged));
    check_eq(Matrix::identity(2), m("1 0; 0 1"));
    check_eq(Matrix::zeros(2, 3).shape(), (2, 3));
});

test("parsing and printing", || {
    check_eq(m("1 2; 3 4").to_string(), "1.00 2.00\n3.00 4.00");
    check_eq("1 x; 2 3".parse::<Matrix>(), Err(MatrixError::Parse("x".to_string())));
    check_eq("1 2; 3".parse::<Matrix>(), Err(MatrixError::Ragged));
    check_eq(m("  -1.5   2 ").to_string(), "-1.50 2.00");
});

test("indexing", || {
    let mut a = m("1 2 3; 4 5 6");
    check_eq(a[(1, 2)], 6.0);
    a[(0, 0)] = 10.0;
    check_eq(a[(0, 0)], 10.0);
    check_panics(|| { let _ = a[(2, 0)]; });
});

test("arithmetic with references", || {
    let a = m("1 2; 3 4");
    let b = m("5 6; 7 8");
    check_eq(&a + &b, m("6 8; 10 12"));
    check_eq(&b - &a, m("4 4; 4 4"));
    check_eq(&a * 2.0, m("2 4; 6 8"));
    check_eq(&a * &b, m("19 22; 43 50"));
    check_eq(&a * &Matrix::identity(2), a.clone());
    check_eq(a[(0, 0)], 1.0);
    check_panics(|| { let _ = &a + &m("1 2 3"); });
});

test("products and transposes", || {
    let a = m("1 2 3; 4 5 6");
    check_eq(a.transpose(), m("1 4; 2 5; 3 6"));
    check_eq(a.try_mul(&a.transpose()), Ok(m("14 32; 32 77")));
    check_eq(a.try_mul(&a), Err(MatrixError::Shape { left: (2, 3), right: (2, 3) }));
    check_panics(|| { let _ = &a * &a; });
});

test("determinants", || {
    check_near(m("4").determinant().unwrap(), 4.0, 1e-9);
    check_near(m("1 2; 3 4").determinant().unwrap(), -2.0, 1e-9);
    check_near(m("2 0 1; 1 3 2; 1 1 2").determinant().unwrap(), 6.0, 1e-9);
    check_near(m("0 1; 1 0").determinant().unwrap(), -1.0, 1e-9);
    check_near(m("1 2; 2 4").determinant().unwrap(), 0.0, 1e-9);
    check_near(m("1 0 2 -1; 3 0 0 5; 2 1 4 -3; 1 0 5 0").determinant().unwrap(), 30.0, 1e-9);
    check_eq(m("1 2 3; 4 5 6").determinant(), Err(MatrixError::NotSquare));
});

